def __find_demographics_tab() -> bool:
    """Searches for the Demographics UI page. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Demographics.dashboard_Demographics_TabItem,30000) is not None else False

def __find_providers_and_facilities_tab() -> bool:
    """Searches for the Providers and Facilities UI page. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Demographics.dashboard_Providers_and_Facilities_TabItem,30000) is not None else False

def __find_select_physician_window() -> bool:
    """Searches for the Select Physician UI Window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Demographics.select_Physician_Window,30000) is not None else False

def await_demographics():
    """
    Wait for Demographics page to appear
    """
    CommonActions.wait_for_object_exists(Demographics.dashboard_Demographics_TabItem)


def click_firstname_edit():
    """
    Click on the patient firstname edit.
    """
    if not __find_demographics_tab():
        raise Exception("Patient demographics tab isn't open!")
    CommonActions.left_click_object(Demographics.firstname_Edit)

def set_firstname(first_name:str, acknowledge_yes:bool=True)-> bool:
    """
    Set the first name if the first name is not same as the input.

    :param str first_name: the first name to set
        bool acknowledge_yes: True, if to click Yes button, False, click No Button
    :return: True or False
    :rtype: bool
    """
    if not __find_demographics_tab():
        raise Exception("Patient demographics tab isn't open!")
    if CommonActions.get_text(Demographics.firstname_Edit) != first_name:
        CommonActions.set_text(Demographics.firstname_Edit, first_name)
        CommonActions.press_tab_key()
        if acknowledge_yes:
            click_yes_on_questions_window()
            return True
        else:
            click_no_on_questions_window()
    return False

def get_firstname() -> str:
    """
    Read the patient first name from the demographics page.

    :return: the first name currently shown
    :rtype: str
    """
    if not __find_demographics_tab():
        raise Exception("Patient demographics tab isn't open!")
    return CommonActions.get_text(Demographics.firstname_Edit)

