def set_birthdate(year: int, month: int, day: int):
    """
    Set/Select the birthdate.

    :param int year, int month, int day:  the year, month and day of the birthdate
    :return: None
    """
    formatted_date = f"{month}/{day}/{year}"
    if CommonActions.get_text(Demographics.birthdate_Edit) != formatted_date:
        CommonActions.set_text(Demographics.birthdate_Edit, formatted_date)

def set_gender(gender:str):
    """
    Select gender from the list

    :param str gender: the gender to set
    :return: None
    """
    gender_str = gender.capitalize() if gender.lower() in ["female", "male", "o"] else gender
    CommonActions.set_text(Demographics.gender_Edit, gender_str)
    CommonActions.press_tab_key()
    if CommonActions.get_text(Demographics.gender_Edit) != gender_str:
        raise Exception("Gender not set")

